#!/usr/bin/env Rscript
suppressPackageStartupMessages({library(data.table);library(digest)})
a<-commandArgs(TRUE);root<-if(length(a))normalizePath(a[1])else normalizePath('.');out<-file.path(root,'paper19opp-revision2/reconstruction/candidate_validation');cross<-file.path(root,'paper19opp-revision2/reconstruction/cross_dataset');inp<-if(length(a)>1)a[2]else file.path(cross,'harmonized_score_part_1.rds')
x<-as.data.table(readRDS(inp));old<-as.data.table(readRDS(file.path(root,'paper19opp-revision1/GitHub/inputs/replogle_scores.rds')));mask<-old[passes_qc_final==TRUE&scDblFinder.class=='singlet',as.character(cell_id)]
stopifnot('cell_id'%in%names(x),'gene'%in%names(x),'gem_group'%in%names(x));x<-x[as.character(cell_id)%in%mask];x[,gene:=as.character(gene)]
axes<-c('apoptosis','proliferation','stress');cols<-paste0('score_',axes);stopifnot(all(cols%in%names(x)))
ctl<-x[gene=='non-targeting'];mu<-vapply(cols,function(v)mean(ctl[[v]]),numeric(1));sdv<-vapply(cols,function(v)sd(ctl[[v]]),numeric(1));stopifnot(all(is.finite(sdv)&sdv>0))
z<-x[gene!='non-targeting',as.list((vapply(.SD,mean,numeric(1))-mu)/sdv),by=gene,.SDcols=cols];setnames(z,cols,paste0('z_',axes));zmat<-as.matrix(z[,paste0('z_',axes),with=FALSE]);p<-max.col(abs(zmat),ties.method='first');z[,target_program:=axes[p]];z[,target_sign:=sign(zmat[cbind(seq_len(nrow(z)),p)])];z[,primary_magnitude:=abs(zmat[cbind(seq_len(nrow(z)),p)])];z[,off_target_magnitude:=sqrt(pmax(rowSums(zmat^2)-primary_magnitude^2,0))];z[,total_response_magnitude:=sqrt(rowSums(zmat^2))]
gm<-x[,lapply(.SD,mean),by=.(gene,gem_group),.SDcols=cols];cm<-gm[gene=='non-targeting'];gg<-gm[gene!='non-targeting'];gg<-merge(gg,cm[,c('gem_group',cols),with=FALSE],by='gem_group',suffixes=c('','_ctrl'))
for(i in seq_along(axes))gg[,(paste0('dz_',axes[i])):=(get(cols[i])-get(paste0(cols[i],'_ctrl')))/sdv[i]]
cos<-function(v,w){den<-sqrt(sum(v*v)*sum(w*w));if(!is.finite(den)||den<1e-12)return(NA_real_);sum(v*w)/den}
rep<-gg[,{overall<-as.numeric(z[match(.BY$gene,gene),paste0('z_',axes),with=FALSE]);m<-as.matrix(.SD);list(median_replicate_cosine=median(apply(m,1,cos,w=overall),na.rm=TRUE),discovery_gem_groups=.N)},by=gene,.SDcols=paste0('dz_',axes)]
cnt<-x[gene!='non-targeting',.(discovery_cells=.N),by=gene];z<-merge(merge(z,rep,by='gene'),cnt,by='gene');z[,priority_score:=primary_magnitude*pmax(median_replicate_cosine,0)/(1+off_target_magnitude)];z[,metadata_eligible:=discovery_cells>=100&discovery_gem_groups>=3&is.finite(priority_score)]
ex<-fread(file.path(cross,'control_gene_expression_source1.tsv'));if(!'gene'%in%names(ex))stop('Need control expression gene column');value<-intersect(c('mean_control_log1p_common_CP10k','mean_logcp10k','control_mean_logcp10k','mean_log1p_cp10k','mean'),names(ex));if(!length(value))stop(paste('Expression value columns:',paste(names(ex),collapse=',')));setnames(ex,value[1],'discovery_control_expression');z<-merge(z,ex[,.(gene,discovery_control_expression)],by='gene',all.x=TRUE)
setorderv(z,c('priority_score','gene'),c(-1,1));z[,global_discovery_rank:=seq_len(.N)];fwrite(z,file.path(out,'harmonized_discovery_ranking.tsv'),sep='\t')
for(st in c('adamson','frangieh')){
 m<-if(st=='adamson')fread(file.path(out,'adamson_metadata_counts.tsv'))else fread(file.path(root,'paper19opp-revision2/reconstruction/external_resources/frangieh_metadata_counts.tsv'))[perturbation_2=='Control',.(gene=perturbation,validation_cells=cells,validation_guides=guide_labels)]
 v<-merge(z,m,by='gene');limit<-if(st=='adamson')100L else 30L;v<-v[metadata_eligible==TRUE&validation_cells>=limit];setorderv(v,c('priority_score','gene'),c(-1,1));v[,candidate_rank:=seq_len(.N)];v[,`:=`(top10=candidate_rank<=10,top20=candidate_rank<=20)];fwrite(v,file.path(out,paste0('harmonized_',st,'_candidates.tsv')),sep='\t');cat(st,nrow(v),'eligiblegenes\n');print(head(v[,.(gene,candidate_rank,priority_score,target_program,target_sign)],20))
}
p<-readLines(file.path(out,'locked_protocol.txt'));p<-c(p,'Final outcome-blind measurement harmonization amendment: one7,848-symbol universe is shared by Replogle,Norman,MIX-Seq,Adamson andFrangieh. Duplicate raw features are summed by gene symbol before log normalization. Each study uses exactly sumcounts overthisuniverse as CP10k denominator and exactly final_axis_membership.tsv module membership.','Unchanged discoverypriorityformula and metadataQC are reapplied to harmonizedReplogle only. Program/sign and ranks are refrozen before externalresponseeffects are evaluated. The original8563-feature and intermediate7851-universe records remain normalization sensitivities, not competing models selected by validation.','Primarycandidateanalysis:2,000gene-bootstrapdraws;200equal-cell resamples;10,000objective-stratified randomsubsets, accepting those whose meanlogexpression/cellcount covariates lie within0.5overallSD of the selectedset. Partialrankadjustments include objective, discovery/validationbaselineexpression and cellcount; addingdiscoverymagnitude testsincrementalcompositesupport.','A discoverycellcount-only ranking is included as an additional simplebaseline. All confidenceintervals conditionon frozenanalysischoices; neither cellresampling nor genebootstrap creates independentbiologicalreplication.');writeLines(p,file.path(out,'harmonized_protocol.txt'))
file.copy(file.path(cross,'final_gene_universe.tsv'),file.path(out,'final_gene_universe.tsv'),overwrite=TRUE);file.copy(file.path(cross,'final_axis_membership.tsv'),file.path(out,'final_axis_membership.tsv'),overwrite=TRUE)
files<-file.path(out,c('harmonized_protocol.txt','harmonized_discovery_ranking.tsv','harmonized_adamson_candidates.tsv','harmonized_frangieh_candidates.tsv','final_gene_universe.tsv','final_axis_membership.tsv','analyze_locked_validation.R'));fwrite(data.table(file=basename(files),sha256=vapply(files,digest,character(1),file=TRUE,algo='sha256')),file.path(out,'harmonized_lock_hashes.tsv'),sep='\t');writeLines(format(Sys.time(),'%Y-%m-%d %H:%M:%S %Z'),file.path(out,'harmonized_lock_time.txt'))
